import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Ten parts, and neither the calendar nor the field is one of them. They are
 * machines of their own, and `connect` hands them **props** — `getCalendarProps`,
 * `getFieldProps` — rather than merging attributes onto their roots: a merge is
 * what would let this picker's `disabled: false` talk over a child that disabled
 * itself, the rule `field` imposed on the whole library.
 *
 * A `root` here, unlike `select`, `menu` and `popover`: the field is not portalled
 * and has to sit beside the trigger. A native combo box is the
 * precedent — it has two *separate* click zones, the field and the
 * button, so the box and the chevron really are two targets and not one
 * button wrapped around a field.
 *
 * No `arrow`: no tang is drawn on a pop-up (`select.anatomy.ts`).
 */
export type DatePickerPart =
  | "root"
  | "label"
  | "trigger"
  | "clearTrigger"
  | "backdrop"
  | "positioner"
  | "content"
  | "title"
  | "cancelTrigger"
  | "closeTrigger";

export const anatomy: Anatomy<DatePickerPart> = createAnatomy("date-picker").parts(
  "root",
  "label",
  "trigger",
  "clearTrigger",
  "backdrop",
  "positioner",
  "content",
  "title",
  "cancelTrigger",
  "closeTrigger",
);

export const parts: Record<DatePickerPart, AnatomyPart> = anatomy.build();

export interface DatePickerCssVars {
  // --- written ---
  /** Where the surface grows from, so a scale-in starts at the anchor. */
  "--sui-transform-origin": "<position>";
  /** Width of the anchor the surface is placed against. */
  "--sui-anchor-width": "<length>";
  /** Height of the anchor the surface is placed against. */
  "--sui-anchor-height": "<length>";
  /** Room left for the surface's width inside the boundary. */
  "--sui-available-width": "<length>";
  /** Room left for the surface's height inside the boundary. */
  "--sui-available-height": "<length>";
  /** Width of the page scrollbar the scroll lock hides, published on the root. */
  "--sui-scrollbar-width": "<length>";
}

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Align, Side } from "../../positioner/compute-position";
import { formatDate } from "../../utils/date-format";
import type { DateValue } from "../../utils/plain-date";
import { parts } from "./date-picker.anatomy";
import {
  getBackdropId,
  getCancelTriggerId,
  getClearTriggerId,
  getCloseTriggerId,
  getContentId,
  getLabelId,
  getPositionerId,
  getRootId,
  getTitleId,
  getTriggerId,
} from "./date-picker.dom";
import type {
  DatePickerApi,
  DatePickerCalendarProps,
  DatePickerFieldProps,
  DatePickerSchema,
} from "./date-picker.types";

/**
 * The caption of a trigger that holds no field — the collapsed chip,
 * whose whole content is the date. Short month, so a chip stays a
 * chip in every locale that spells "September" out.
 */
const CAPTION_FORMAT: Intl.DateTimeFormatOptions = {
  day: "numeric",
  month: "short",
  year: "numeric",
};

export function connect<T extends PropTypes>(
  service: Service<DatePickerSchema>,
  normalize: NormalizeProps<T>,
): DatePickerApi<T> {
  const { context, computed, prop, send, scope } = service;

  const open = context.get("open");
  const value = context.get("value");
  const hasValue = computed("hasValue");
  const hasTitle = context.get("hasTitle");
  const hasLabel = context.get("hasLabel");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");
  const required = prop("required");
  const dir = prop("dir");
  const locale = prop("locale") ?? "en-US";
  const presentation = computed("presentation");
  const state = open ? "open" : "closed";
  const stateAttrs = { "data-state": state, "data-presentation": presentation };
  const placement = context.get("currentPlacement");
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const rootId = getRootId(scope);
  const labelId = getLabelId(scope);
  const triggerId = getTriggerId(scope);
  const contentId = getContentId(scope);
  const titleId = getTitleId(scope);

  const valueText = value === null ? "" : formatDate(value, locale, CAPTION_FORMAT);
  const canClear = prop("clearable") && hasValue && !disabled && !readOnly;
  const labelledBy = prop("labelledBy");
  const label = prop("label");

  /**
   * The two children, driven by props and never by merged attributes: a merge
   * would let this picker's `disabled: false` talk over a calendar or a field that
   * disabled itself (the rule `field` set).
   *
   * The two handlers are separate on purpose. A day chosen in the grid is a
   * decision and closes the surface; a date typed in the field is a keystroke and
   * must not — the year is nearly always the last unit filled, and a field that
   * closed the picker halfway through a date would be unusable.
   */
  const calendarProps: DatePickerCalendarProps = {
    value,
    onValueChange: (details) => send({ type: "CALENDAR.SELECT", value: details.value }),
    focusedValue: context.get("focusedValue"),
    onFocusChange: (details) => send({ type: "CALENDAR.PAGE", value: details.value }),
    today: prop("today"),
    min: prop("min"),
    max: prop("max"),
    isDateUnavailable: prop("isDateUnavailable"),
    // The resolved locale, not the raw prop. `undefined` does not mean the same
    // thing to the two children: the field pins `en-US` so the segment *order*
    // cannot differ between server and client (date-field.machine.ts:165-169),
    // while the calendar falls through to the document via `ENVIRONMENT.SYNC`
    // (calendar.machine.ts:219). Relaying the raw prop let one picker render a
    // French grid above American segments.
    locale,
    dir,
    readOnly,
    disabled,
    invalid,
    intents: prop("intents"),
  };

  const fieldProps: DatePickerFieldProps = {
    value,
    onValueChange: (details) => send({ type: "FIELD.CHANGE", value: details.value }),
    // The field bounds with `DateValue | undefined`, the picker with a nullable —
    // `null` is how a consumer clears a bound they were passing.
    min: prop("min") ?? undefined,
    max: prop("max") ?? undefined,
    // Resolved, for the reason given on the calendar's line above: one locale
    // decides both children or neither.
    locale,
    dir,
    disabled,
    readOnly,
    required,
    invalid,
    // The form is the field's: this anatomy has no hidden input of its own.
    name: prop("name"),
    form: prop("form"),
    // An explicit `labelledBy` wins — it is what a `field` above hands down, and
    // "inherits the field it sits in" is a contract with a test of its own. The
    // rendered `label` part is the *fallback*, and it is the half that was
    // missing: relaying the prop alone left that part with an id nothing
    // referenced, so a picker standing on its own handed a reader an anonymous
    // group of spinbuttons in every story that rendered one.
    //
    // Note the precedence is the opposite of `color-picker`, which lets its own
    // label part win over `labelledBy`. Only one of the two can be right; this one
    // has the `field` contract behind it.
    labelledBy: labelledBy ?? (hasLabel ? labelId : undefined),
    describedBy: prop("describedBy"),
    intents: prop("intents"),
  };

  return {
    open,
    value,
    hasValue,
    valueText,
    presentation,
    placement,
    triggerId,
    contentId,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    setValue(next: DateValue | null): void {
      send({ type: "VALUE.SET", value: next });
    },

    clearValue(): void {
      send({ type: "VALUE.SET", value: null });
    },

    getCalendarProps: (): DatePickerCalendarProps => calendarProps,
    getFieldProps: (): DatePickerFieldProps => fieldProps,

    /**
     * A real element, unlike `select`'s and `menu`'s: the field is not portalled
     * and has to sit beside the trigger. A native combo box is the
     * precedent — two click zones, one box.
     */
    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: rootId,
        dir,
        ...stateAttrs,
        "data-disabled": dataAttr(disabled),
        "data-readonly": dataAttr(readOnly),
        "data-invalid": dataAttr(invalid),
        "data-placeholder": dataAttr(!hasValue),
      }),

    /**
     * An id and nothing else, the calendar's own arrangement: nothing references
     * this automatically. A label written blind into `aria-labelledby` is a
     * dangling IDREF the day a consumer renders no label, so the wiring is
     * `labelledBy` — which is also what a `field` above hands down.
     */
    getLabelProps: (): T["element"] =>
      normalize.element({
        ...parts.label.attrs,
        id: labelId,
        "data-disabled": dataAttr(disabled),
        "data-invalid": dataAttr(invalid),
      }),

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: triggerId,
        type: "button",
        // `readOnly` does not close the surface off: a date nobody may change is
        // still a date somebody may want to look at in context, which is exactly
        // the split `calendar` makes between choosing a cell and walking to one.
        disabled,
        "aria-haspopup": "dialog",
        "aria-expanded": boolAttr(open),
        // Omitted while the surface is unmounted: an IDREF pointing at nothing is
        // an `aria-valid-attr-value` violation, and this content is portalled and
        // gone between opens.
        "aria-controls": open ? contentId : undefined,
        // The label *and* the date. Both attributes replace the element's text, so
        // either one alone left a chip trigger, whose whole content is the date,
        // announced as "Due date" and never which day it holds. The trigger's own
        // id says "and my contents", the `color-picker` arrangement; a string label
        // cannot be referenced, so `aria-label` writes the caption out instead.
        "aria-labelledby": labelledBy && `${labelledBy} ${triggerId}`,
        // Withheld under `labelledBy` so the control keeps one voice; ARIA would
        // rank them the same way, but two sources is two chances to disagree.
        "aria-label": labelledBy
          ? undefined
          : label && valueText
            ? `${label}, ${valueText}`
            : label,
        "aria-describedby": prop("describedBy"),
        "aria-invalid": ariaAttr(invalid),
        ...stateAttrs,
        "data-placeholder": dataAttr(!hasValue),
        "data-disabled": dataAttr(disabled),
        "data-readonly": dataAttr(readOnly),
        "data-invalid": dataAttr(invalid),
        // The click and nothing else — no press-drag-release, unlike the select's
        // trigger: there is no list to drag onto, and the second press on the same
        // button is a close rather than a re-open.
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
      }),

    /**
     * Opt-in through `clearable`, and `disabled` rather than absent when there is
     * nothing to clear: a control that vanishes as it is pressed moves everything
     * beside it, and the tab order with it.
     */
    getClearTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.clearTrigger.attrs,
        id: getClearTriggerId(scope),
        type: "button",
        disabled: !canClear,
        "data-disabled": dataAttr(!canClear),
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLEAR.CLICK" });
        },
      }),

    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        ...stateAttrs,
      }),

    /**
     * The floating element. `data-side`/`data-align` are deliberately absent here —
     * the position effect writes onto this node directly, and an adapter that also
     * rendered them would fight it over every commit. They are published on
     * `content`, from `currentPlacement`.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-sui-layer-parent": prop("parentId"),
        ...stateAttrs,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: contentId,
        role: "dialog",
        // The sheet is the only modal presentation: an anchored popup leaves the
        // page live behind it, and claiming otherwise would make every reader
        // believe the app had stopped.
        "aria-modal": computed("isModal") ? "true" : undefined,
        dir: context.get("surfaceDir") ?? dir,
        tabIndex: -1,
        // A rendered title names the surface; failing that the trigger does, which
        // is always in the document. Never both.
        "aria-labelledby": hasTitle ? titleId : triggerId,
        ...stateAttrs,
        "data-side": side,
        "data-align": align,
        "data-placement": placement,
        // The surface applies the glass material, so it owes its contents
        // the on-glass palette (architecture.md).
        "data-sui-on-glass": "",
        "data-snav": "container",
        "data-snav-trap": computed("isModal") ? "" : undefined,
      }),

    getTitleProps: (): T["element"] => normalize.element({ ...parts.title.attrs, id: titleId }),

    /**
     * Sheet only, and a sibling of the grid. `tabindex="-1"`: a pointer and touch
     * affordance whose keyboard and screen-reader path is Escape and B — the
     * `select:cancel-trigger` precedent, kept. Not `aria-hidden`, because
     * explore-by-touch has to be able to land on it.
     */
    getCancelTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        id: getCancelTriggerId(scope),
        type: "button",
        tabIndex: -1,
        ...stateAttrs,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.CLICK" });
        },
      }),

    /**
     * A composition point, so it declares only its placement and the rest of its
     * shape sits behind `:not([data-part*=" "])`. No name of its own: the core
     * emits none, and a consumer who renders it supplies one — the rule
     * `dialog:close-trigger` already lives by.
     */
    getCloseTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.closeTrigger.attrs,
        id: getCloseTriggerId(scope),
        type: "button",
        ...stateAttrs,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "date-picker";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getClearTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "clear-trigger");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getTitleId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "title");
}

export function getCancelTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "cancel-trigger");
}

export function getCloseTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "close-trigger");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

/**
 * By id and not by a query rooted on the surface: the part is a composition point
 * a consumer may place inside the content or beside it in the positioner, and both
 * are the same close button.
 */
export function getCloseTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getCloseTriggerId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/**
 * Rooted on the positioner rather than on the content, the popover's arrangement:
 * a title is inside the surface, but a part probed from the surface alone would
 * miss anything a consumer places beside it in the positioner.
 */
export function hasTitle(scope: Scope): boolean {
  return query(getPositionerEl(scope), '[data-part~="date-picker:title"]') !== null;
}

/**
 * Rooted on the root, not the positioner: the label sits beside the trigger and
 * the field, outside the surface entirely — the mirror of `hasTitle` above.
 */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), '[data-part~="date-picker:label"]') !== null;
}

/**
 * Where the focus goes when the surface opens: the day, which the APG's Date
 * Picker Dialog asks for by name.
 *
 * Asked of ARIA rather than of the calendar's own part vocabulary, and that is the
 * whole reason it works: a `role="grid"` has exactly one roving tab stop, so this
 * selector names "the cell the grid would hand the keyboard" without the picker
 * knowing which component drew the grid — or whether the surface holds one at all.
 */
export function getInitialCellEl(scope: Scope): HTMLElement | null {
  return query(getContentEl(scope), '[role="gridcell"][tabindex="0"]');
}

/** The same three fallbacks as the select's: no document, no throw. */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  const rendered = getRootEl(scope) ?? getContentEl(scope) ?? getTriggerEl(scope);
  if (rendered !== null) return rendered;
  const root = scope.getRootNode();
  if (root === null) return null;
  return (root.ownerDocument ?? (root as Document)).documentElement;
}

/**
 * The date picker is the select's surface with a *date* — and, unlike the select,
 * it owns none of what is inside it. The month grid is a `calendar` and the typed
 * date is a `date-field`, two machines this one drives **by props**
 * (`getCalendarProps`, `getFieldProps`) rather than by reaching into them
 * That is the whole reason the family is three
 * components: an inline calendar has one state and pays none of the eight effects
 * below, and a birth-date field needs no surface at all (§2).
 *
 * Everything structural here is `select.machine.ts`, kept verbatim so the two
 * surfaces cannot drift: two states projecting `context.open`, `PRESENTATION.SYNC`
 * re-entering `open` on a density flip, `captureFinalFocus` on the **exit** of
 * `closed` (the interpreter installs effects before entry actions, and an effect
 * that hides or moves things would blur the trigger before it was captured), and
 * the eight effects of `select.machine.ts:389-398`. The two that close the
 * select's list are deliberately not taken: there is no selection blink on a
 * grid, and a month does not scroll, so neither `trackSelectionFlash` nor
 * `trackScrollEdges` has anything to say here (§5.3).
 *
 * What `open` adds is an entry, `focusInitialCell` — `select.machine.ts:387` is
 * the precedent, `highlightInitial`. The APG's Date Picker Dialog opens onto the
 * day, and the day is the grid's single roving tab stop, so the picker can put the
 * focus there without knowing which component drew the grid.
 */

import { hasAccessibleName } from "../../a11y/accessible-name";
import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { addDomEvent } from "../../dom/event";
import { timeout } from "../../dom/raf";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { focusWentElsewhere, restoreFocus } from "../../focus/restore-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getFirstTabbable } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { Density, Direction } from "../../types";
import { getToday } from "../../utils/date-format";
import { isDev } from "../../utils/env";
import { shallowEqual } from "../../utils/equality";
import { warn } from "../../utils/invariant";
import { clampDate, type DateValue } from "../../utils/plain-date";
import {
  getBackdropId,
  getCancelTriggerId,
  getCloseTriggerEl,
  getContentEl,
  getContentId,
  getEnvironmentEl,
  getInitialCellEl,
  getPositionerEl,
  getRootEl,
  getTriggerEl,
  hasLabel,
  hasTitle,
} from "./date-picker.dom";
import type { DatePickerSchema } from "./date-picker.types";

type Params = MachineParams<DatePickerSchema>;

/** The inline properties `trackPosition` writes and never cleans up itself. */
const POSITION_STYLES = [
  "position",
  "top",
  "left",
  "transform",
  "width",
  "--sui-transform-origin",
] as const;

/**
 * How long a swallowed outside press keeps waiting for the click that belongs to
 * it. The select's constant, and the select's reason: a trusted click follows its
 * own pointerup within a frame, so the fuse only exists for a gesture that ended
 * in a drag and will never produce one.
 */
const OUTSIDE_CLICK_FUSE_MS = 300;

/**
 * One shape for the value, whichever child reported it. A `date-field` at a finer
 * granularity hands back an object with `hour` on it, and `shallowEqual` compares
 * key sets — so a value that round-tripped through the field would never compare
 * equal to the same day chosen in the grid, and every commit would notify.
 */
function toPlainDate(value: DateValue | null): DateValue | null {
  if (value === null) return null;
  return { year: value.year, month: value.month, day: value.day };
}

/**
 * Kept word for word from `dialog`, `menu` and `popover`. `select` has its own and
 * it is deliberately not this one: its trigger renders the picked value as real
 * text, so it asks `labels`/`closest("label")` where this asks `textContent`. A
 * date-picker trigger renders nothing by default, which is why it takes this side.
 */
/**
 * `PRESENTATION.SYNC` re-enters `open` from `open`, so the two focus-moving pieces
 * would replay on a live density flip: `focusContent` puts the focus back in the
 * surface, `focusInitialCell` moves it onto the day, and whoever was typing in the
 * segmented field — which is not portalled, and sits outside `content` entirely —
 * loses the caret mid-date. The six other effects genuinely must rebuild, which is
 * why the reentry stays and only these two are silenced.
 *
 * Both halves of the reentry, not just the reinstall: the interpreter tears the
 * effects down before it installs them again, and `focusContent`'s disposer would
 * otherwise see the focus still inside the surface and hand it back to the trigger.
 * That disposer belongs to the install the *open* made, so the event has to be read
 * live at teardown rather than captured when the effect went in.
 */
function isPresentationReentry(event: Params["event"]): boolean {
  return event.type === "PRESENTATION.SYNC";
}

function commit(params: Params, value: DateValue | null): void {
  params.context.set("value", toPlainDate(value));
}

export const machine: Machine<DatePickerSchema> = createMachine<DatePickerSchema>({
  props({ props }) {
    return {
      defaultValue: null,
      defaultOpen: false,
      presentation: "auto",
      closeOnSelect: true,
      clearable: false,
      placement: "bottom-start",
      gap: 4,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      // The select's `true` inverted, and the reason is the content: a listbox is
      // a widened trigger, a month is seven cells wide whatever the field measures.
      matchWidth: false,
      strategy: "fixed",
      closeOnEscape: true,
      closeOnInteractOutside: true,
      preventOutsideActivation: true,
      modal: false,
      restoreFocus: true,
      readOnly: false,
      required: false,
      invalid: false,
      disabled: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    // Read once for the life of the service: `context` runs once, while every
    // `init` below is re-invoked on each read, so a clock placed inside one would
    // be consulted on every property access. The calendar narrows the same
    // divergence the same way — the markup depends on the page, not on the day.
    const fallbackPage = prop("today") ?? getToday();

    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "date-picker open",
      })),
      value: bindable<DateValue | null>(() => ({
        defaultValue: prop("defaultValue") ?? null,
        value: prop("value"),
        // Without it every commit would be a fresh object, and both children —
        // a month of 42 cells and a strip of spinbuttons — would re-render for a
        // date that had not moved.
        isEqual: shallowEqual,
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "date-picker value",
      })),
      /**
       * Internal, and deliberately not a prop: a consumer who wants a page names a
       * `defaultValue`. What it exists for is the seam — the calendar is controlled
       * on it, so a date typed in the field moves the grid and a grid that paged
       * itself is where the next open starts.
       */
      focusedValue: bindable<DateValue>(() => ({
        defaultValue: clampDate(
          prop("value") ?? prop("defaultValue") ?? fallbackPage,
          prop("min"),
          prop("max"),
        ),
        isEqual: shallowEqual,
      })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      currentPlacement: bindable(() => ({ defaultValue: prop("placement") })),
      hasTitle: bindable<boolean>(() => ({ defaultValue: false })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    presentation({ prop, context }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      return context.get("density") === "touch" ? "sheet" : "popup";
    },
    hasValue: ({ context }) => context.get("value") !== null,
    /**
     * One answer for every consequence of modality: `aria-modal`, the spatial
     * trap, the dismissable layer and `hideOutside`. Four sites tested `modal`
     * alone until 2026-09-06, so `modal` on an anchored popup hid the whole page
     * from assistive technology and trapped the d-pad, while the surface itself
     * correctly declined to claim `aria-modal`. `lockPageScroll` stays out of
     * this on purpose: it answers the *presentation*, because a sheet covers the
     * screen whether or not it is modal (`preventScroll` says so in its type).
     */
    isModal: ({ prop, computed }) => computed("presentation") === "sheet" && prop("modal"),
  },

  /**
   * No `initialValue` photo here. One was written until 2026-09-06, with a comment
   * promising "the field's own `FORM.RESET`" — a reset this machine never had, and
   * never needs: the form is the field's (`getFieldProps`, and this anatomy has no
   * hidden input of its own), so a reset restores the field, which reports back
   * through `onValueChange` like any other edit. The ref was written once and read
   * nowhere.
   */
  refs() {
    return { finalFocusEl: null };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackEnvironment"],

  watch({ context, computed, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    track(
      () => [computed("presentation")],
      () => send({ type: "PRESENTATION.SYNC" }),
    );
    // The one place the two children are joined: a date arriving from either of
    // them moves the page, so the grid shows the month of what was just typed
    // rather than the month it happened to be on.
    track(
      () => [context.get("value")],
      () => action(["syncPage"]),
    );
    // The popover's arrangement, and no effect of its own: the title mounts with
    // the surface in the same commit, and an adapter plays its watchers after that
    // commit — so reading the DOM here is reading it once it exists.
    track(
      () => [hasTitle(scope), hasLabel(scope)],
      () => action(["syncParts"]),
    );
  },

  on: {
    "VALUE.SET": { actions: ["setValue"] },
    "FIELD.CHANGE": { actions: ["setValue"] },
    "CALENDAR.PAGE": { actions: ["setPage"] },
    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    // The density flip tears the open state down and builds it back: the position
    // tracker leaves, the scroll lock arrives, the geometry changes.
    //
    // `select.machine.ts:381` re-enters the same way and replays the same two
    // focus-moving pieces — `focusContent` and the entry `highlightInitial`, which
    // calls `focusHighlightedItem` with no read of the active element either. The
    // gate below is taken here and not there because the exposure is not the same:
    // a select's surface holds everything a person can be doing, while this one has
    // a segmented field beside it, outside `content`, where a date is typed while
    // the grid is open. Named debt (audit of 2026-09-06), and the two files must be
    // settled together — the select's `PRESENTATION.SYNC` wants the twin comment.
    "PRESENTATION.SYNC": { guard: "isOpen", target: "open", reenter: true },
    "PARTS.SYNC": { actions: ["syncParts"] },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "CLEAR.CLICK": { guard: "isClearable", actions: ["clearValue"] },
  },

  states: {
    closed: {
      // Exit rather than the open state's entry, for the select's reason: the
      // interpreter installs effects before entry actions, and an effect that
      // hides or moves things would blur the trigger before it was captured.
      exit: ["captureFinalFocus"],
      on: {
        "TRIGGER.CLICK": { guard: "isEnabled", actions: ["openPicker"] },
      },
    },
    open: {
      entry: ["focusInitialCell"],
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        // Before anything that moves the focus. A focus landing in a surface still
        // parked at `0,0` scrolls the page there to reveal it.
        "trackAnchorPosition",
        "focusContent",
        "proxyTabs",
        "hideOutside",
        "captureIntents",
        "warnCloseTriggerName",
      ],
      on: {
        // A disclosure, not the select's open-only trigger: the same button closes.
        "TRIGGER.CLICK": { actions: ["closePicker"] },
        "CALENDAR.SELECT": [
          { guard: "shouldCloseOnSelect", actions: ["commitValue", "closePicker"] },
          { actions: ["commitValue"] },
        ],
        // Never a commit: Escape, an outside press and B all leave the value alone.
        "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closePicker"] },
        "CANCEL.CLICK": { actions: ["invokeOnDismiss", "closePicker"] },
        "CLOSE.CLICK": { actions: ["closePicker"] },
      },
    },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),
      isClearable: ({ prop }) => prop("clearable") && !prop("disabled") && !prop("readOnly"),
      shouldCloseOnSelect: ({ prop }) => prop("closeOnSelect"),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        return prop("closeOnInteractOutside");
      },
    },

    actions: {
      openPicker({ context }) {
        context.set("open", true);
      },

      closePicker({ context }) {
        context.set("open", false);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      /**
       * The open state's **entry** — after the effects, after the adapter has
       * painted — so the grid exists and `focusContent` has already put the focus
       * in the surface. This moves it onto the day the APG asks for, and falls back
       * to the first tabbable for a surface that holds no grid at all.
       *
       * Not on a reentry: see `isPresentationReentry`.
       */
      focusInitialCell({ event, scope }) {
        if (isPresentationReentry(event)) return;
        const content = getContentEl(scope);
        if (content === null) return;
        const target = getInitialCellEl(scope) ?? getFirstTabbable(content);
        if (target !== null) focusElement(target);
      },

      commitValue(params) {
        if (params.event.type === "CALENDAR.SELECT") commit(params, params.event.value);
      },

      setValue(params) {
        const { event } = params;
        if (event.type === "VALUE.SET" || event.type === "FIELD.CHANGE") {
          commit(params, event.value);
        }
      },

      clearValue({ context }) {
        context.set("value", null);
      },

      setPage({ context, event }) {
        if (event.type === "CALENDAR.PAGE") context.set("focusedValue", event.value);
      },

      /**
       * A cleared value leaves the page where it was: the month somebody was
       * looking at is not something a clear button asked to change.
       */
      syncPage({ context }) {
        const value = context.get("value");
        if (value !== null) context.set("focusedValue", value);
      },

      /**
       * One action for both ways out that are not a commit. The cancel button is
       * the touch twin of the B button, so it reports the same reason — the
       * layer-stack vocabulary has no "cancel", and inventing one would be a change
       * to another component's contract.
       */
      invokeOnDismiss({ prop, event }) {
        prop("onDismiss")?.({ reason: event.type === "CONTENT.DISMISS" ? event.reason : "back" });
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },

      syncParts({ context, scope }) {
        context.set("hasTitle", hasTitle(scope));
        context.set("hasLabel", hasLabel(scope));
      },
    },

    effects: {
      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        // Said here, where the DOM is already being read, and said once — the
        // select's arrangement (`trackCollection`), for the select's reason: an
        // `aria-haspopup="dialog"` button demands a name and this component can
        // invent none. The rendered `label` part names the *field*, never this,
        // so `label`, `labelledBy` or a `field` above is the whole of it.
        // **Absent is not nameless** — nothing is rendered on a server, and a
        // machine that never started never reaches this line.
        const trigger = getTriggerEl(scope);
        warn(
          isDev() && trigger !== null && !hasAccessibleName(trigger),
          "a date picker has no accessible name — pass `label` or `labelledBy`, or render it inside a `field`",
        );
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      /**
       * The surface is the one part that emits a `dir` nobody asked for, and the
       * portal is the whole reason: inheritance does not cross one, so the
       * direction has to be carried over explicitly. Read from the trigger, never
       * from the surface, which sits in the body and would only report the
       * document's own direction back to itself — and in an effect rather than in
       * `connect`, so the server emits nothing and the first client render has
       * nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getTriggerEl(scope)));
      },

      /**
       * Parity M5, inherited from the select: `preventOutsideActivation` makes the
       * click that closes a picker stop there instead of activating what was
       * underneath. The swallow logic lives in the shared layer options.
       */
      trackDismissable({ prop, computed, scope, send }) {
        const content = getContentEl(scope);
        const doc = content?.ownerDocument;
        const win = doc?.defaultView ?? null;

        return trackDismissableLayer(content, {
          id: getContentId(scope),
          type: "dialog",
          modal: computed("isModal"),
          parentId: prop("parentId"),
          // The root and not just the trigger. This is the first component whose
          // `root` holds other controls beside the trigger — the segmented field,
          // the clear button, the label — and the shape was inherited from `select`,
          // where the trigger is all there is. With the surface open, a click on the
          // clear button was "outside": the pointerdown was prevented, the click
          // that followed was cancelled in capture, the surface closed and the focus
          // went back to the trigger, so the button did nothing on the first press
          // (audit of 2026-09-05). Same widening as `color-picker.surface.ts:77-81`.
          // The sheet's cancel too: it sits beside the content, so a press on it
          // was outside and reported `outside-pointer` instead of its own `back`
          // (R59). The cancel alone and not the positioner, whose box no stylesheet
          // is trusted to keep out of the pointer's way (decision 01). The close
          // trigger for the same reason when it is placed there (R62).
          exclude: () => [
            getRootEl(scope),
            scope.getById(getCancelTriggerId(scope)),
            getCloseTriggerEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          onPointerDownOutside(event) {
            if (!prop("preventOutsideActivation") || doc === undefined || win === null) return;
            event.preventDefault();
            let cancelFuse: VoidFunction | undefined;
            const removeClick = addDomEvent(
              doc,
              "click",
              (click) => {
                click.preventDefault();
                click.stopPropagation();
                cancelFuse?.();
              },
              { capture: true, once: true },
            );
            // A trusted click follows its own pointerup within a frame; the fuse
            // only exists so a gesture that ended in a drag cannot leave a listener
            // waiting for a click nobody meant.
            cancelFuse = timeout(win, removeClick, OUTSIDE_CLICK_FUSE_MS);
          },
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      lockPageScroll({ prop, computed, scope }) {
        if (computed("presentation") === "sheet" && prop("preventScroll") !== false) {
          return lockScroll(getContentEl(scope)?.ownerDocument);
        }
      },

      /**
       * The sheet branch clears what a previous popup pass left behind, on install
       * rather than on teardown: a disposer would run while `presence` still holds
       * the node for its exit, and the surface would snap to `0,0` mid-fade.
       */
      trackAnchorPosition({ prop, computed, scope, send }) {
        const positioner = getPositionerEl(scope);
        if (positioner === null) return;

        if (computed("presentation") !== "popup") {
          for (const name of POSITION_STYLES) positioner.style.removeProperty(name);
          return;
        }

        return trackPosition(getTriggerEl(scope), positioner, {
          placement: prop("placement"),
          gap: prop("gap"),
          offset: prop("offset"),
          flip: prop("flip"),
          shift: prop("shift"),
          padding: prop("padding"),
          matchWidth: prop("matchWidth"),
          // From the trigger, not from the surface: the surface is portalled into
          // `document.body` and would report the document direction, while the
          // alignment belongs to the region the trigger sits in.
          dir: resolveDir(prop("dir"), getTriggerEl(scope)),
          strategy: prop("strategy"),
          boundary: prop("boundary"),
          getAnchorRect: prop("getAnchorRect"),
          onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
        });
      },

      /**
       * The surface takes the focus so the keys reach it; `focusInitialCell` moves
       * it onto the day straight after, from the open state's entry.
       *
       * The disposer is the restore, and it fires when the focus is inside the
       * layer or nowhere (`body`, read on the document, since a shadow root
       * answers `null` for any focus outside it): a person who focused something
       * else, by a click or by tabbing past the trigger, has already said where
       * they want to be. Nowhere covers WebKit, which never focuses a pressed
       * button, so a real press on the trigger blurs the day onto `body` (R63),
       * and a press on blank space with `preventOutsideActivation={false}`.
       * The layer is the positioner, not the content: a press on the sheet's
       * cancel beside it focuses the cancel. A trigger disabled while open takes
       * nothing, so `restoreFocus` falls back on its neighbour (R58).
       *
       * Neither half runs for a reentry: see `isPresentationReentry`.
       */
      focusContent(params) {
        const { prop, refs, scope } = params;
        const content = getContentEl(scope);
        if (content === null) return;
        const layer = getPositionerEl(scope) ?? content;
        if (!isPresentationReentry(params.event)) focusElement(content);
        return () => {
          if (isPresentationReentry(params.event) || !prop("restoreFocus")) return;
          if (focusWentElsewhere(scope.getDoc(), layer, scope.getActiveElement())) return;
          restoreFocus(
            prop("finalFocus")?.() ?? refs.get("finalFocusEl") ?? getTriggerEl(scope),
            layer,
          );
        };
      },

      /**
       * Non-modal, Tab out of the portalled surface goes where the author wrote
       * it: past the trigger, or back onto it.
       *
       * Modal (`isModal`), `hideOutside` makes the trigger and everything around
       * it inert, so there is no "after the trigger" — and unlike `select` and
       * `menu`, Tab does not close this surface, so `placeOnDispose` has nothing
       * to place. Until 2026-10-11 the proxy still handed the step to the inert
       * trigger and the key died on the edge. The proxy now reads the inert
       * trigger and the content's `aria-modal="true"` (from `isModal`) and
       * wraps: Tab from the last stop goes to the first, and
       * back, the grid one stop. Inside a modal dialog, the dialog's trap holds
       * the key for the proxy (`holdTab`, `claimTab`) and stands down.
       *
       * Not `trapFocus`, measured: wiring the trap here cost the date family 62 B
       * gzip, and the family sits 10 B under its CDC ceiling (`scripts/size-budget.ts`).
       * The intents are left alone either way, so the pad still walks the grid.
       */
      proxyTabs({ scope }) {
        return proxyTabFocus(getContentEl(scope), {
          triggerNode: () => getTriggerEl(scope),
        });
      },

      hideOutside({ prop, computed, scope }) {
        if (!computed("isModal")) return;
        return hideOthers(
          [
            getContentEl(scope),
            getPositionerEl(scope),
            scope.getById(getBackdropId(scope)),
            ...(prop("persistentElements")?.() ?? []),
          ],
          { inert: true },
        );
      },

      /**
       * **B and nothing else**. The calendar inside
       * this surface pushed its own scope while it mounted — an adapter starts a
       * child's machine before the parent's watchers run — so this scope sits on
       * top of it, and every intent it declines falls straight through to the grid:
       * the directions, A, and LT/RT for the month. Claiming any of them here would
       * take them away from the component that already answers them.
       *
       * Not `trapped`, the popover's reason kept: a trapped scope answers
       * `consumed` to what it refuses, which would silence the calendar underneath
       * it and the spatial engine at the bottom of the stack.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);

        return host.pushScope((event) => {
          if (event.intent !== "back") return false;
          // The top-most test and not `ownsFocus`: B is the way back out of a
          // layer whether or not the pad ever walked into it, and a picker with
          // something opened over it must not answer for that layer's B.
          if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
          send({ type: "CONTENT.DISMISS", reason: "back" });
          return true;
        });
      },

      /**
       * `close-trigger` is the one part here that carries no name of its own — the
       * consumer gives it one or does not render it, the rule
       * `dialog:close-trigger` lives by — and until 2026-09-06 nothing said so out
       * loud, while `dialog`, `menu` and `popover` all warn for the same part. In
       * the open state because that is when the part exists, and looked up by id
       * rather than queried, so a consumer who places it beside the surface in the
       * positioner is heard too.
       */
      warnCloseTriggerName({ scope }) {
        const close = getCloseTriggerEl(scope);
        warn(
          isDev() && close !== null && !hasAccessibleName(close),
          "a date picker close trigger has no accessible name — give it text, `aria-label` or `title`",
        );
      },
    },
  },
});

import type { DismissReason } from "../../interaction/layer-stack";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Density, Direction, Rect } from "../../types";
import type { DateValue } from "../../utils/plain-date";

/** What the surface actually is once the density has had its say. */
export type DatePickerPresentation = "popup" | "sheet";

export type DatePickerPresentationProp = "auto" | DatePickerPresentation;

export interface DatePickerValueChangeDetails {
  readonly value: DateValue | null;
}

export interface DatePickerOpenChangeDetails {
  readonly open: boolean;
}

export interface DatePickerFocusChangeDetails {
  readonly value: DateValue;
}

export interface DatePickerDismissDetails {
  readonly reason: DismissReason;
}

/**
 * The machine props this picker hands its calendar. **Props, never merged
 * attributes**: a merge would let the picker's
 * `disabled: false` talk over a calendar that disabled itself, which is the rule
 * `field` imposed on every control below it.
 *
 * Assignability to `CalendarMachineProps` is what the adapter checks by spreading it onto
 * a calendar root — stated structurally here so the picker's types do not have to
 * reach into a sibling component's module.
 */
export interface DatePickerCalendarProps {
  readonly value: DateValue | null;
  readonly onValueChange: (details: DatePickerValueChangeDetails) => void;
  /**
   * The page, controlled from here — a calendar's anchor *is* the month it shows.
   * The picker holds it because it is the only one that sees both children: a date
   * typed in the field has to move the grid, and a grid that paged itself has to be
   * where the next open starts.
   */
  readonly focusedValue: DateValue;
  readonly onFocusChange: (details: DatePickerFocusChangeDetails) => void;
  readonly today: DateValue | undefined;
  readonly min: DateValue | null | undefined;
  readonly max: DateValue | null | undefined;
  readonly isDateUnavailable: ((value: DateValue) => boolean) | undefined;
  readonly locale: string | undefined;
  readonly dir: Direction | undefined;
  readonly readOnly: boolean;
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly intents: IntentScopeHost | null | undefined;
}

/**
 * The machine props this picker hands its date field — the same descent, and the
 * one that carries the form: the picker's anatomy has no hidden input, so `name`
 * and `form` are the field's to submit.
 */
export interface DatePickerFieldProps {
  readonly value: DateValue | null;
  readonly onValueChange: (details: DatePickerValueChangeDetails) => void;
  readonly min: DateValue | undefined;
  readonly max: DateValue | undefined;
  readonly locale: string | undefined;
  readonly dir: Direction | undefined;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly invalid: boolean;
  readonly name: string | undefined;
  readonly form: string | undefined;
  readonly labelledBy: string | undefined;
  readonly describedBy: string | undefined;
  readonly intents: IntentScopeHost | null | undefined;
}

export interface DatePickerMachineProps {
  // --- value -----------------------------------------------------------------
  /**
   * A civil date and nothing finer: `commit` narrows every value to year, month
   * and day, whichever child reported it, so the grid and the field cannot report
   * two shapes of the same date.
   *
   * The consequence, stated because it used to be stated the other way round: a
   * `date-field` given a time `granularity` inside a picker does **not** keep its
   * own time. The picker *controls* the field's value, so the narrowed date is
   * handed straight back and the time segments are cleared on every commit. A
   * picker is a day picker; a time belongs to a field standing on its own, and to
   * the `time-field` presentation the spec defers.
   */
  readonly value?: DateValue | null | undefined;
  readonly defaultValue?: DateValue | null | undefined;
  readonly onValueChange?: ((details: DatePickerValueChangeDetails) => void) | undefined;
  /** Renders the `clearTrigger`; without it the part is inert furniture. */
  readonly clearable?: boolean | undefined;

  // --- openness --------------------------------------------------------------
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly onOpenChange?: ((details: DatePickerOpenChangeDetails) => void) | undefined;
  readonly presentation?: DatePickerPresentationProp | undefined;
  /** A chosen day closes the surface. `false` keeps it out for a second choice. */
  readonly closeOnSelect?: boolean | undefined;

  // --- positioning, handed straight to the positioner ------------------------
  readonly placement?: Placement | undefined;
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  /**
   * `false` by default — the divergence from `select`, whose surface is a widened
   * trigger. A month is seven cells wide whatever the field beside it measures.
   */
  readonly matchWidth?: boolean | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;
  readonly getAnchorRect?: (() => Rect) | undefined;

  // --- relayed to the children ------------------------------------------------
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /**
   * Pinned rather than read from the environment, for `date-field`'s reason: the
   * locale decides the *order* of the segments and the wording of the trigger's
   * caption, so a locale resolved from the browser would have the server and the
   * client render different markup and hydration would say so.
   */
  readonly locale?: string | undefined;
  readonly today?: DateValue | undefined;
  readonly min?: DateValue | null | undefined;
  readonly max?: DateValue | null | undefined;
  readonly isDateUnavailable?: ((value: DateValue) => boolean) | undefined;
  readonly readOnly?: boolean | undefined;

  // --- dismissal (the select's defaults) ---------------------------------------
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  readonly preventOutsideActivation?: boolean | undefined;
  readonly modal?: boolean | undefined;
  /** Defaults to the `sheet` presentation and is ignored in `popup`. */
  readonly preventScroll?: boolean | undefined;
  readonly onDismiss?: ((details: DatePickerDismissDetails) => void) | undefined;
  /**
   * The layer this picker opened from — required once either end is portalled, or
   * a click inside the portalled surface reads as outside the layer that holds the
   * trigger. Adapters default it from their layer context.
   */
  readonly parentId?: string | undefined;

  // --- focus -----------------------------------------------------------------
  readonly restoreFocus?: boolean | undefined;
  readonly finalFocus?: (() => HTMLElement | null) | undefined;
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;

  // --- form (the field's, relayed) --------------------------------------------
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly required?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly disabled?: boolean | undefined;

  // --- naming ------------------------------------------------------------------
  /** `aria-label` for the trigger when nothing in it says what it opens. */
  readonly label?: string | undefined;
  /** `aria-labelledby` for the trigger and the field — what a `field` wires in. */
  readonly labelledBy?: string | undefined;
  readonly describedBy?: string | undefined;
  readonly intents?: IntentScopeHost | null | undefined;
}

export interface ResolvedDatePickerMachineProps extends DatePickerMachineProps {
  readonly defaultValue: DateValue | null;
  readonly defaultOpen: boolean;
  readonly presentation: DatePickerPresentationProp;
  readonly closeOnSelect: boolean;
  readonly clearable: boolean;
  readonly placement: Placement;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly matchWidth: boolean;
  readonly strategy: "absolute" | "fixed";
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly preventOutsideActivation: boolean;
  readonly modal: boolean;
  readonly restoreFocus: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly invalid: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface DatePickerSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedDatePickerMachineProps;
  context: {
    /** The single source of truth; the state is a projection of it. */
    open: boolean;
    /** The app's date. Both children are controlled from it, so nothing drifts. */
    value: DateValue | null;
    /**
     * The month on screen, and the grid's roving anchor — one and the same thing,
     * which is the calendar's own founding decision. Held here rather than left to
     * the calendar because the picker is the only one that sees both children.
     */
    focusedValue: DateValue;
    density: Density;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
    /** Where the surface landed — the preferred placement may have flipped. */
    currentPlacement: Placement;
    /** Whether a `title` is rendered; a `role="dialog"` names itself from one. */
    hasTitle: boolean;
    /**
     * Whether a `label` part is rendered. The field's `role="group"` is what
     * carries the accessible name, and it only
     * ever got one from a consumer's `labelledBy` — so a picker that rendered the
     * label part the anatomy gives it stayed anonymous.
     */
    hasLabel: boolean;
  };
  computed: {
    presentation: DatePickerPresentation;
    hasValue: boolean;
    /**
     * Modality is one question, so it is answered once. `modal` alone is not it:
     * an anchored popup leaves the page live behind it whatever the prop says.
     */
    isModal: boolean;
  };
  refs: {
    finalFocusEl: HTMLElement | null;
  };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "CLEAR.CLICK" }
    /** A day chosen in the calendar — the one path `closeOnSelect` answers. */
    | { type: "CALENDAR.SELECT"; value: DateValue | null }
    /** The grid paged itself: an arrow off the edge, a header button, a trigger. */
    | { type: "CALENDAR.PAGE"; value: DateValue }
    /** A date typed in the field. Never closes: the typing is not finished. */
    | { type: "FIELD.CHANGE"; value: DateValue | null }
    /** `api.setValue`/`clearValue` — never touches `open`. */
    | { type: "VALUE.SET"; value: DateValue | null }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CANCEL.CLICK" }
    | { type: "CLOSE.CLICK" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" }
    | { type: "PRESENTATION.SYNC" }
    | { type: "PARTS.SYNC" }
    | { type: "ENVIRONMENT.SYNC"; density: Density };
  action:
    | "openPicker"
    | "closePicker"
    | "setOpen"
    | "captureFinalFocus"
    | "focusInitialCell"
    | "commitValue"
    | "setValue"
    | "clearValue"
    | "setPage"
    | "syncPage"
    | "invokeOnDismiss"
    | "syncEnvironment"
    | "syncPlacement"
    | "syncParts";
  guard: "isEnabled" | "isOpen" | "isClearable" | "shouldCloseOnSelect" | "canDismiss";
  effect:
    | "trackEnvironment"
    | "trackSurfaceDir"
    | "trackDismissable"
    | "lockPageScroll"
    | "trackAnchorPosition"
    | "focusContent"
    | "proxyTabs"
    | "hideOutside"
    | "captureIntents"
    | "warnCloseTriggerName";
}

export interface DatePickerApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly value: DateValue | null;
  readonly hasValue: boolean;
  /**
   * The value written out for a trigger that has no field in it — the touch chip,
   * whose whole content is the date. Empty string when there is none.
   */
  readonly valueText: string;
  readonly presentation: DatePickerPresentation;
  /** Where the surface landed, which is not necessarily what was asked for. */
  readonly placement: Placement;
  readonly triggerId: string;
  readonly contentId: string;

  setOpen(open: boolean): void;
  setValue(value: DateValue | null): void;
  /** Sugar for `setValue(null)`. */
  clearValue(): void;

  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getTriggerProps(): T["button"];
  getClearTriggerProps(): T["button"];
  getBackdropProps(): T["element"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
  getTitleProps(): T["element"];
  getCancelTriggerProps(): T["button"];
  getCloseTriggerProps(): T["button"];
  /** Machine props for the calendar this picker holds — spread, never merged. */
  getCalendarProps(): DatePickerCalendarProps;
  /** Machine props for the date field beside the trigger — spread, never merged. */
  getFieldProps(): DatePickerFieldProps;
}

